// ScratchPad/Session15/Session15ConstraintDemo.cs
public sealed class Session15ConstraintDemo
{
    public void Run()
    {
        int higherNumber = SelectGreater(15, 27);
        Console.WriteLine($"Higher number: {higherNumber}");

        var firstEmployee = new Employee(15, "Avery", new Address { City = "Springfield" });
        var secondEmployee = new Employee(27, "Morgan", new Address { City = "Riverton" });

        // Does not compile: Employee does not implement IComparable<Employee>.
        // Employee laterEmployee = SelectGreater(firstEmployee, secondEmployee);
    }

    private static T SelectGreater<T>(T left, T right)
        where T : IComparable<T>
    {
        int comparison = left.CompareTo(right);
        return comparison >= 0 ? left : right;
    }
}

// Append to ScratchPad/Program.cs without removing earlier calls.
var session15 = new Session15ConstraintDemo();
session15.Run();
